function fileToDataUri(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// Resizes + JPEG-compresses an uploaded image in the browser before storing it,
// since this environment has no object-storage backend — this at least keeps
// stored payloads small instead of raw multi-MB base64 photos.
function compressImage(file, maxDim = 900, quality = 0.75) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const reader = new FileReader();
    reader.onload = () => {
      img.onload = () => {
        let { width, height } = img;
        if (width > maxDim || height > maxDim) {
          if (width > height) { height = Math.round((height * maxDim) / width); width = maxDim; }
          else { width = Math.round((width * maxDim) / height); height = maxDim; }
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

const MAX_IMAGE_MB = 5;
// Compresses the image client-side, then returns it as a base64 data URL that
// gets stored directly as a field on the store/product's own Firestore
// document — NOT uploaded to Firebase Storage. This is deliberate: Storage
// requires the paid "Blaze" plan (a linked card), while Firestore itself is
// free on the "Spark" plan with no card needed. This is safe here because
// each store and each product already lives in its OWN Firestore document
// (see firestoreApi.js) — a compressed photo (usually 50-200KB) comfortably
// fits inside Firestore's 1MB-per-document limit. If you later upgrade to
// Blaze and want real file storage, swap this function's body for a call to
// uploadStoreImage() from firestoreApi.js — nothing else needs to change.
async function handleImageUpload(file, onError) {
  if (!file.type.startsWith("image/")) { onError("Sirf image files allowed hain (jpg, png, webp)."); return null; }
  if (file.size > MAX_IMAGE_MB * 1024 * 1024) { onError(`Image ${MAX_IMAGE_MB}MB se chhoti honi chahiye.`); return null; }
  try {
    return await compressImage(file);
  } catch {
    onError("Image process nahi ho payi, dobara try karo.");
    return null;
  }
}

// Locks page scroll while a mobile drawer/sheet (menu, cart) is open.
function useBodyScrollLock(locked) {
  useEffect(() => {
    if (!locked) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = prev; };
  }, [locked]);
}

