function getStoreStatus(store) {
  const now = Date.now();
  if (store.blocked) return { status: "blocked", daysLeft: 0 };
  if (store.plan && store.planExpiresAt && new Date(store.planExpiresAt).getTime() > now) {
    const daysLeft = Math.ceil((new Date(store.planExpiresAt).getTime() - now) / 86400000);
    return { status: "active", daysLeft, plan: store.plan };
  }
  if (store.trialStartedAt) {
    const trialEnd = new Date(store.trialStartedAt).getTime() + TRIAL_DAYS * 86400000;
    if (trialEnd > now) {
      const daysLeft = Math.ceil((trialEnd - now) / 86400000);
      return { status: "trial", daysLeft };
    }
  }
  return { status: "expired", daysLeft: 0 };
}

function slugify(s) {
  return s.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}
function discountPct(mrp, price) {
  if (!mrp || mrp <= price) return 0;
  return Math.round(((mrp - price) / mrp) * 100);
}

