function Button({ children, onClick, variant = "primary", style, type = "button", disabled }) {
  const base = { fontFamily: "Inter", fontWeight: 600, fontSize: 15, padding: "11px 20px", borderRadius: 8, border: "none", cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? 0.5 : 1, transition: "opacity 0.15s ease, transform 0.08s ease" };
  const variants = {
    primary: { background: T.marigold, color: "#fff" },
    magenta: { background: T.magenta, color: "#fff" },
    ghost: { background: "transparent", color: T.ink, border: `1px solid ${T.border}` },
    dark: { background: T.ink, color: "#fff" },
    mint: { background: T.mint, color: "#fff" },
  };
  return (
    <button type={type} disabled={disabled} onClick={onClick}
      onMouseDown={(e) => (e.currentTarget.style.transform = "scale(0.98)")}
      onMouseUp={(e) => (e.currentTarget.style.transform = "scale(1)")}
      style={{ ...base, ...variants[variant], ...style }}>
      {children}
    </button>
  );
}

