  const [authUser, setAuthUser] = useState(undefined);
  const [view, setView] = useState("directory");
  const [activeStoreId, setActiveStoreId] = useState(null);
  useEffect(() => {
  const params = new URLSearchParams(window.location.search);
  const storeId = params.get("store");

  if (storeId) {
    setActiveStoreId(storeId);
    setView("storefront");
  }
}, []);
  const [toast, setToast] = useState("");
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [showCart, setShowCart] = useState(false);
  const checkoutInFlight = useRef(false);
  const createStoreInFlight = useRef(false);
  const didInitialAuthRedirect = useRef(false);

  const flash = (m) => { setToast(m); setTimeout(() => setToast(""), 2200); };
  const [saveState, setSaveState] = useState("idle"); // idle | saving | error — drives the small "Saving..." indicator in the Dashboard header

  // Merges the separately-fetched profiles/products/orders back into the same
  // shape the rest of the app (and every existing component) already expects
  // — a store object with .products and .orders arrays on it — so none of
  // the UI/JSX below needs to change.
  const stores = useMemo(
    () => storeProfiles.map((s) => ({
      ...s,
      products: productsByStore[s.id] || [],
      orders: ordersByStore[s.id] || [],
    })),
    [storeProfiles, productsByStore, ordersByStore]
  );

  
  useEffect(() => {
    ensureFonts();
    const onErr = (source) => (err) => { setLoadError({ err, source }); setLoading(false); };
    const unsubStores = watchAllStores((data) => { setStoreProfiles(data); setLoading(false); }, onErr("stores"));
    const unsubProducts = watchAllProducts(setProductsByStore, onErr("products"));
    const unsubAuth = watchAuthState(setAuthUser);
    // Safety net: if Firestore never calls back at all (wrong project ID,
    // network block, etc.) — neither success nor error — don't hang on
    // "Loading…" forever with zero explanation.
    const timeout = setTimeout(() => {
      setLoading((stillLoading) => {
        if (stillLoading) setLoadError({ err: new Error("Firebase se 10 second mein koi jawab nahi mila — VITE_FIREBASE_PROJECT_ID aur baaki env vars check karo."), source: "timeout" });
        return stillLoading;
      });
    }, 10000);
    return () => { unsubStores(); unsubProducts(); unsubAuth(); clearTimeout(timeout); };
  }, []);

  useEffect(() => {
    if (authUser === undefined) return;
    if (!authUser) {
      setOrdersByStore({});
      return;
    }
    const unsubOrders = watchAllOrders(setOrdersByStore, (err) => { setLoadError({ err, source: "orders" }); setLoading(false); });
    return () => unsubOrders();
  }, [authUser]);

  // authUser is a real, persisted Firebase Auth session — it survives page
  // reloads on its own, unlike the old in-memory-only `session` state. The
  // Super Admin is just the Firebase user whose email matches SUPER_ADMIN_EMAIL;
  // there's no separate password constant to compare against any more.
  const isSuperAdmin = !!authUser && authUser.email === SUPER_ADMIN_EMAIL;
  const session = authUser && !isSuperAdmin ? authUser.uid : null;

  // On first load, if the browser already has a persisted login, jump
  // straight to the right screen instead of showing the public directory
  // and making the person navigate manually.
  useEffect(() => {
    if (authUser === undefined || didInitialAuthRedirect.current) return;
    didInitialAuthRedirect.current = true;
    if (authUser) setView(isSuperAdmin ? "superadmin" : "dashboard");
  }, [authUser, isSuperAdmin]);

  const activeStore =
  stores.find((s) => s.id === activeStoreId) ||
  stores.find((s) => s.slug === activeStoreId);
  console.log("ActiveStoreId =", activeStoreId);
  console.log("Stores =", stores);
  console.log("ActiveStore =", activeStore);
  useEffect(() => {
  if (!stores.length) return;

  const params = new URLSearchParams(window.location.search);
  const queryStore = params.get("store");
  console.log("Query Store:", queryStore);
  console.log("Stores:", stores);

  if (queryStore) {
    const store = stores.find(
      (s) => s.id === queryStore || s.slug === queryStore
    );

    if (store) {
      setActiveStoreId(store.id);
      setView("storefront");
      return;
    }
  }

  const path = window.location.pathname.replace("/", "");

  if (!path) return;

  const store = stores.find(
    (s) => s.id === path || s.slug === path
  );

  if (store) {
    setActiveStoreId(store.id);
    setView("storefront");
  }
}, [stores]);
  const ownerStore = stores.find((s) => s.id === session);

  // Real Firebase Authentication — see firestoreApi.js. Passwords are never
