function AuthCard({ title, children }) {
  return (
    <div style={{ maxWidth: 420, margin: "60px auto", padding: "0 20px" }}>
      <div style={{ background: T.cream, border: `1px solid ${T.border}`, borderRadius: 16, padding: 30, boxShadow: "0 4px 20px rgba(0,0,0,0.10)" }}>
        <h2 style={{ fontFamily: "Inter", fontSize: 24, color: T.ink, marginTop: 0 }}>{title}</h2>
        {children}
      </div>
    </div>
  );
}

const THEME_ICONS = { classic: "🛍️", modern: "✨", aurora: "🌌", luxe: "👑", freshmarket: "🥦", fashionstudio: "👗", neoncommerce: "⚡", universalmodern: "💎" };
const THEME_DESCS = {
  classic: "Simple aur professional",
  modern: "App jaisa, bottom navigation",
  aurora: "Premium modern, blue gradient",
  luxe: "Dark & gold, luxury feel",
  freshmarket: "Green & fresh, grocery style",
  fashionstudio: "Minimal elegant, beige tones",
  neoncommerce: "Dark neon, glow effects",
  universalmodern: "Ultra-premium, auto-colors from your logo, dark mode",
};

function ThemePicker({ value, onChange }) {
  const order = ["classic", "modern", "aurora", "luxe", "freshmarket", "fashionstudio", "neoncommerce", "universalmodern"];
  return (
    <div style={{ marginBottom: 16 }}>
      <span style={{ fontFamily: "Inter", fontWeight: 600, fontSize: 13, color: T.ink, opacity: 0.75, display: "block", marginBottom: 8 }}>Store ka Theme</span>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        {order.map((key) => {
          const P = getThemePreset(key === "classic" ? "modern" : key);
          const bg = key === "classic" ? `linear-gradient(135deg, ${T.marigold}33, ${T.marigold}11)` : `linear-gradient(135deg, ${P.bannerFrom}, ${P.bannerTo})`;
          const active = value === key;
          return (
            <button key={key} type="button" onClick={() => onChange(key)} style={{ padding: 0, cursor: "pointer", border: active ? `2px solid ${T.magenta}` : `1px solid ${T.border}`, borderRadius: 12, overflow: "hidden", background: "#fff", textAlign: "left" }}>
              <div style={{ height: 60, background: bg, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}>{THEME_ICONS[key]}</div>
              <div style={{ padding: "8px 10px" }}>
                <div style={{ fontWeight: 700, fontSize: 12.5, color: T.ink }}>{key === "classic" ? "Classic" : P.label}</div>
                <div style={{ fontSize: 10, color: T.ink, opacity: 0.6 }}>{THEME_DESCS[key]}</div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function SignupForm({ onSubmit, onLogin }) {
  const [f, setF] = useState({ name: "", tagline: "", whatsapp: "", email: "", password: "", color: T.marigold, theme: "classic" });
  const [touched, setTouched] = useState({});
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const colors = [T.marigold, T.magenta, T.mint, "#3D5A80", "#8338EC"];

  const errors = {
    whatsapp: f.whatsapp && !isValidPhone(f.whatsapp) ? "10-digit WhatsApp number chahiye (e.g. 919876543210)" : "",
    email: f.email && !isValidEmail(f.email) ? "Sahi email daalo" : "",
    password: f.password && f.password.length < 6 ? "Password kam se kam 6 characters ka ho" : "",
  };
  const hasErrors = Object.values(errors).some(Boolean);
  const canSubmit = f.name.trim() && f.whatsapp.trim() && f.email.trim() && f.password.trim() && !hasErrors;

  return (
    <AuthCard title="Apna Store Banao 🎉">
      <Field label="Store ka naam" placeholder="e.g. Sharma Kirana Store" value={f.name} onChange={set("name")} />
      <Field label="Tagline (optional)" placeholder="e.g. Only Wholesale" value={f.tagline} onChange={set("tagline")} />
      <Field label="WhatsApp number (with country code, no +)" placeholder="919876543210" value={f.whatsapp} onChange={set("whatsapp")} onBlur={() => setTouched({ ...touched, whatsapp: true })} inputMode="numeric" />
      {touched.whatsapp && errors.whatsapp && <div style={{ color: T.red, fontSize: 12, marginTop: -10, marginBottom: 12 }}>{errors.whatsapp}</div>}
      <Field label="Login Email" type="email" placeholder="you@email.com" value={f.email} onChange={set("email")} onBlur={() => setTouched({ ...touched, email: true })} />
      {touched.email && errors.email && <div style={{ color: T.red, fontSize: 12, marginTop: -10, marginBottom: 12 }}>{errors.email}</div>}
      <Field label="Login Password" type="password" placeholder="••••••" value={f.password} onChange={set("password")} onBlur={() => setTouched({ ...touched, password: true })} />
      {touched.password && errors.password && <div style={{ color: T.red, fontSize: 12, marginTop: -10, marginBottom: 12 }}>{errors.password}</div>}
      <div style={{ marginBottom: 16 }}>
        <span style={{ fontFamily: "Inter", fontWeight: 600, fontSize: 13, color: T.ink, opacity: 0.75 }}>Store colour</span>
        <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
          {colors.map((c) => (
            <button key={c} type="button" aria-label={`Color ${c} chuno`} aria-pressed={f.color === c} onClick={() => setF({ ...f, color: c })} style={{ width: 36, height: 36, minHeight: 36, borderRadius: 8, background: c, border: f.color === c ? `2px solid ${T.ink}` : `1px solid ${T.border}`, cursor: "pointer", padding: 0 }} />
          ))}
        </div>
      </div>
      <ThemePicker value={f.theme} onChange={(theme) => setF({ ...f, theme })} />
      <Button style={{ width: "100%" }} disabled={!canSubmit} onClick={() => onSubmit(f)}>Store Banao →</Button>
      <p style={{ textAlign: "center", fontSize: 13, marginTop: 14, color: T.ink }}>
        Pehle se account hai? <button style={{ color: T.magenta, cursor: "pointer", fontWeight: 600, background: "transparent", border: "none", padding: 0, font: "inherit" }} onClick={onLogin}>Login karo</button>
      </p>
    </AuthCard>
  );
}

