                {c}<button aria-label={`${c} category delete karo`} style={{ cursor: "pointer", color: T.magenta, background: "transparent", border: "none", padding: "8px", marginRight: -8, fontSize: 13 }} onClick={() => { if (window.confirm(`"${c}" category delete karni hai?`)) onDeleteCategory(c); }}>✕</button>
