                      <button onClick={() => onChangeQty(p.id + "|", 1)} aria-label="Quantity badhao" style={{ padding: "6px 12px", minHeight: 32, cursor: "pointer", fontWeight: 800, background: P.isDark ? "#1a1a2e" : T.paper, border: "none", color: P.textColor }}>+</button>
