function AdminProgressBar({ status, daysLeft, totalDays }) {
  const pct = totalDays ? Math.max(0, Math.min(100, Math.round(((totalDays - daysLeft) / totalDays) * 100))) : 100;
  const color = status === "blocked" ? "#DC2626" : status === "expired" ? "#9CA3AF" : status === "trial" ? "#F59E0B" : T.mint;
  const label = status === "blocked" ? "Manually blocked" : status === "expired" ? "Plan expired" : status === "trial" ? `Trial — ${daysLeft} din baaki` : `Active plan — ${daysLeft} din baaki`;
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
        <span style={{ fontSize: 11.5, color: T.ink, fontWeight: 600 }}>{label}</span>
        <span style={{ fontSize: 11.5, color: T.muted, fontWeight: 600 }}>{status === "blocked" ? "" : `${pct}%`}</span>
      </div>
      <div style={{ height: 6, borderRadius: 4, background: "#F1F2F4", overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${status === "blocked" ? 100 : pct}%`, background: color, borderRadius: 4, transition: "width 0.4s ease" }} />
      </div>
    </div>
  );
}

function SuperAdminDashboard({ stores, onActivate, onBlock, onExtendTrial, onLogout, onResetPassword }) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [sortBy, setSortBy] = useState("newest");
  const [page, setPage] = useState(1);
  const PER_PAGE = 8;

  const enriched = useMemo(() => stores.map((s) => ({ ...s, _status: getStoreStatus(s) })), [stores]);

  const stats = useMemo(() => {
    const total = enriched.length;
    const active = enriched.filter((s) => s._status.status === "active").length;
    const blocked = enriched.filter((s) => s.blocked).length;
    const weekAgo = Date.now() - 7 * 86400000;
    const newThisWeek = enriched.filter((s) => s.trialStartedAt && new Date(s.trialStartedAt).getTime() > weekAgo).length;
    const revenue = enriched.filter((s) => s._status.status === "active" && s.plan).reduce((sum, s) => sum + (PLAN_PRICES[s.plan]?.price || 0), 0);
    return { total, active, blocked, newThisWeek, revenue };
  }, [enriched]);

  const filtered = useMemo(() => {
    let list = enriched;
    if (statusFilter !== "all") list = list.filter((s) => s._status.status === statusFilter);
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter((s) => s.name.toLowerCase().includes(q) || s.id.toLowerCase().includes(q) || s.email.toLowerCase().includes(q));
    }
    const sorted = [...list];
    if (sortBy === "newest") sorted.sort((a, b) => new Date(b.trialStartedAt || 0) - new Date(a.trialStartedAt || 0));
    else if (sortBy === "name") sorted.sort((a, b) => a.name.localeCompare(b.name));
    else if (sortBy === "daysleft") sorted.sort((a, b) => a._status.daysLeft - b._status.daysLeft);
    return sorted;
  }, [enriched, statusFilter, search, sortBy]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));
  const pageItems = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);
  useEffect(() => { setPage(1); }, [statusFilter, search, sortBy]);

  return (
    <div style={{ background: "#FAFAFA", minHeight: "100vh" }}>
      <style>{`
        .sads-admin-actions { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; }
        @media (max-width: 720px) { .sads-admin-actions { grid-template-columns: repeat(2, 1fr); } }
        .sads-admin-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
        @media (max-width: 860px) { .sads-admin-stats { grid-template-columns: repeat(2, 1fr); } }
        .sads-admin-meta { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
        @media (max-width: 560px) { .sads-admin-meta { grid-template-columns: 1fr 1fr; } }
        @keyframes sadsAdminFadeIn { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
        .sads-admin-fade { animation: sadsAdminFadeIn 0.2s ease; }
      `}</style>

      {/* Premium sticky header */}
      <div style={{ position: "sticky", top: 0, zIndex: 30, background: "rgba(255,255,255,0.85)", backdropFilter: "blur(14px)", WebkitBackdropFilter: "blur(14px)", borderBottom: `1px solid ${T.border}` }}>
        <div style={{ maxWidth: 1180, margin: "0 auto", padding: "12px 20px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Logo size={26} />
            <span style={{ background: "#111827", color: "#fff", fontSize: 10, fontWeight: 800, letterSpacing: "0.04em", padding: "4px 9px", borderRadius: 20 }}>SUPER ADMIN</span>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <button aria-label="Search" style={{ width: 38, height: 38, borderRadius: 10, border: `1px solid ${T.border}`, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: T.ink }}><Search size={16} /></button>
            <button aria-label="Notifications" style={{ width: 38, height: 38, borderRadius: 10, border: `1px solid ${T.border}`, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: T.ink }}><Bell size={16} /></button>
            <div style={{ width: 38, height: 38, borderRadius: 10, background: `linear-gradient(135deg, ${T.mint}, #0B7A4A)`, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontWeight: 800, fontSize: 12 }}>AM</div>
            <button onClick={onLogout} style={{ display: "flex", alignItems: "center", gap: 6, border: `1px solid ${T.border}`, background: "#fff", color: T.ink, borderRadius: 10, padding: "9px 14px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", minHeight: 38 }}>
              <LogOut size={14} /> Logout
            </button>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "24px 20px 80px" }}>
        {/* Stats */}
        <div className="sads-admin-stats" style={{ marginBottom: 28 }}>
          <AdminStatCard icon={Store} label="Total Stores" value={stats.total} sub={stats.newThisWeek > 0 ? `+${stats.newThisWeek} is hafte` : "Is hafte koi naya nahi"} tint={T.mint} />
          <AdminStatCard icon={TrendingUp} label="Active Stores" value={stats.active} sub={stats.total ? `${Math.round((stats.active / stats.total) * 100)}% of total` : "—"} tint="#2563EB" />
          <AdminStatCard icon={QrCode} label="Active Plans Revenue" value={`₹${stats.revenue.toLocaleString("en-IN")}`} sub="Current active paid plans" tint="#F59E0B" />
          <AdminStatCard icon={Ban} label="Blocked Stores" value={stats.blocked} sub={stats.blocked > 0 ? "Review karo" : "Sab clear"} tint="#DC2626" />
        </div>

        {/* Toolbar: search, filter, sort */}
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 20 }}>
          <div style={{ position: "relative", flex: "1 1 220px" }}>
            <Search size={15} color={T.muted} style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)" }} />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Store naam, ID ya email search karo..." style={{ width: "100%", minHeight: 42, padding: "0 12px 0 34px", borderRadius: 10, border: `1px solid ${T.border}`, fontFamily: "Inter", fontSize: 13.5, background: "#fff", boxSizing: "border-box" }} />
          </div>
          <div style={{ position: "relative" }}>
            <Filter size={14} color={T.muted} style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }} />
            <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ minHeight: 42, padding: "0 14px 0 32px", borderRadius: 10, border: `1px solid ${T.border}`, fontFamily: "Inter", fontSize: 13, background: "#fff", cursor: "pointer" }}>
              <option value="all">Sab Status</option>
              <option value="active">Active</option>
              <option value="trial">Trial</option>
              <option value="expired">Expired</option>
              <option value="blocked">Blocked</option>
            </select>
          </div>
          <div style={{ position: "relative" }}>
            <ArrowUpDown size={13} color={T.muted} style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }} />
            <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} style={{ minHeight: 42, padding: "0 14px 0 32px", borderRadius: 10, border: `1px solid ${T.border}`, fontFamily: "Inter", fontSize: 13, background: "#fff", cursor: "pointer" }}>
              <option value="newest">Newest</option>
              <option value="name">Name A-Z</option>
              <option value="daysleft">Days Left</option>
            </select>
          </div>
        </div>

        <div style={{ fontSize: 12.5, color: T.muted, marginBottom: 14, fontWeight: 600 }}>{filtered.length} store{filtered.length !== 1 ? "s" : ""} mila</div>

        {/* Store cards */}
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          {pageItems.map((s) => {
            const st = s._status;
            const totalDays = st.status === "active" ? (PLAN_PRICES[st.plan]?.days || 30) : st.status === "trial" ? TRIAL_DAYS : 0;
            return (
              <div key={s.id} style={{ background: "#fff", border: `1px solid ${T.border}`, borderRadius: 16, padding: 20, boxShadow: "0 1px 3px rgba(17,24,39,0.05)" }}>
                {/* Row 1 */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12, marginBottom: 12 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 0 }}>
                    {s.logoImg ? (
                      <img src={s.logoImg} alt="" style={{ width: 44, height: 44, borderRadius: 12, objectFit: "cover", flexShrink: 0 }} />
                    ) : (
                      <div style={{ width: 44, height: 44, borderRadius: 12, background: `linear-gradient(135deg, ${s.color || T.mint}, #0B7A4A)`, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontWeight: 800, fontSize: 14, flexShrink: 0 }}>{s.name.slice(0, 2).toUpperCase()}</div>
                    )}
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontFamily: "Inter", fontWeight: 700, fontSize: 20, color: T.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{s.name}</div>
                      <div style={{ fontSize: 12, color: T.muted, fontFamily: "monospace" }}>@{s.id}</div>
                    </div>
                  </div>
                  <AdminStatusBadge status={st.status} />
                </div>

                {/* Row 2 */}
                <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 18px", marginBottom: 14, fontSize: 12.5, color: T.muted }}>
                  <span><Mail size={12} style={{ verticalAlign: -1, marginRight: 4 }} />{s.email}</span>
                  <span><Phone size={12} style={{ verticalAlign: -1, marginRight: 4 }} />{s.whatsapp}</span>
                  <span><QrCode size={12} style={{ verticalAlign: -1, marginRight: 4 }} />{st.plan ? PLAN_PRICES[st.plan]?.label : "No paid plan"}</span>
                </div>

                {/* Password reset — Super Admin only. Real Firebase Auth never lets
                    anyone read a password back in plain text (that's the whole point
                    of it being secure), so instead this sends the seller a real email
                    with a link to set a new password themselves. */}
                <div style={{ background: "#FFFBEB", border: "1px solid #FDE68A", borderRadius: 10, padding: "10px 12px", marginBottom: 14 }}>
                  <button
                    onClick={() => onResetPassword(s.email)}
                    style={{ display: "flex", alignItems: "center", gap: 6, background: "transparent", border: "none", cursor: "pointer", color: "#92400E", fontSize: 12, fontWeight: 700, padding: 0, minHeight: 28 }}
                  >
                    <Lock size={12} />
                    Password Reset Email Bhejo
                  </button>
                  <div style={{ fontSize: 11.5, color: "#92400E", opacity: 0.8, marginTop: 4 }}>
                    Seller ko {s.email} par ek link jayega jisse woh khud naya password set kar sake.
                  </div>
                </div>

                {/* Row 3 — progress */}
                <div style={{ marginBottom: 16 }}>
                  <AdminProgressBar status={st.status} daysLeft={st.daysLeft} totalDays={totalDays} />
                </div>

                {/* Actions */}
                <div className="sads-admin-actions" style={{ marginBottom: 16 }}>
                  <AdminActionBtn icon={Clock} label="+7 Days" sub="Trial" onClick={() => onExtendTrial(s.id, 7)} />
                  <AdminActionBtn icon={QrCode} label="₹500" sub="Monthly" tone="primary" onClick={() => onActivate(s.id, "monthly")} />
                  <AdminActionBtn icon={QrCode} label="₹1350" sub="3 Months" onClick={() => onActivate(s.id, "quarterly")} />
                  <AdminActionBtn icon={QrCode} label="₹3000" sub="Yearly" tone="dark" onClick={() => onActivate(s.id, "yearly")} />
                  <AdminActionBtn icon={Ban} label={s.blocked ? "Unblock" : "Block"} tone={s.blocked ? "primary" : "danger"} onClick={() => onBlock(s.id)} />
                </div>

                {/* Bottom meta */}
                <div className="sads-admin-meta" style={{ paddingTop: 14, borderTop: `1px solid ${T.border}` }}>
                  <div>
                    <div style={{ fontSize: 10.5, color: T.muted, fontWeight: 600, display: "flex", alignItems: "center", gap: 4 }}><CalendarDays size={11} /> Created</div>
                    <div style={{ fontSize: 12, color: T.ink, fontWeight: 600, marginTop: 2 }}>{s.trialStartedAt ? new Date(s.trialStartedAt).toLocaleDateString("en-IN") : "—"}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 10.5, color: T.muted, fontWeight: 600, display: "flex", alignItems: "center", gap: 4 }}><CalendarDays size={11} /> Expiry</div>
                    <div style={{ fontSize: 12, color: T.ink, fontWeight: 600, marginTop: 2 }}>{s.planExpiresAt ? new Date(s.planExpiresAt).toLocaleDateString("en-IN") : st.status === "trial" ? "Trial" : "—"}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 10.5, color: T.muted, fontWeight: 600, display: "flex", alignItems: "center", gap: 4 }}><Hash size={11} /> Store ID</div>
                    <div style={{ fontSize: 12, color: T.ink, fontWeight: 600, marginTop: 2, fontFamily: "monospace" }}>{s.id}</div>
                  </div>
                </div>
              </div>
            );
          })}
          {pageItems.length === 0 && (
            <div style={{ textAlign: "center", padding: "60px 20px", color: T.muted, fontSize: 14 }}>Koi store nahi mila.</div>
          )}
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: 6, marginTop: 26 }}>
            <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1} aria-label="Previous page" style={{ width: 36, height: 36, borderRadius: 10, border: `1px solid ${T.border}`, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: page === 1 ? "not-allowed" : "pointer", opacity: page === 1 ? 0.4 : 1, color: T.ink }}><ChevronLeft size={16} /></button>
            <span style={{ fontSize: 12.5, color: T.muted, fontWeight: 600, padding: "0 8px" }}>Page {page} / {totalPages}</span>
            <button onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page === totalPages} aria-label="Next page" style={{ width: 36, height: 36, borderRadius: 10, border: `1px solid ${T.border}`, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: page === totalPages ? "not-allowed" : "pointer", opacity: page === totalPages ? 0.4 : 1, color: T.ink }}><ChevronRight size={16} /></button>
          </div>
        )}
      </div>
    </div>
  );
}
